/* app.js — 攀岩 splat 原型的 app 邏輯: 離線佇列 / EXIF / 觸發瀏覽器內 SfM */
(function () {
  "use strict";
  const $ = (id) => document.getElementById(id);
  const logEl = $("log");
  let lastResultUrl = null;
  let cvReadyPromise = null;

  function log(msg, cls) {
    const line = document.createElement("div");
    if (cls) line.className = cls;
    line.textContent = msg;
    logEl.appendChild(line);
    logEl.scrollTop = logEl.scrollHeight;
  }
  function clearLog() { logEl.innerHTML = ""; }

  /* ---------------- IndexedDB 佇列 ----------------
   * 有些 webview 會封鎖 IndexedDB，或在主執行緒被檢視器占滿時讓它的
   * 回呼遲遲不觸發；任一步驟失敗或逾時就退回記憶體佇列，讓本 session
   * 的流程（載入範例 → 重建）照常走完，而不是按了按鈕什麼都不發生。 */
  const DB_NAME = "climb-splat-db", STORE = "photos";
  let idbBroken = false;
  const memItems = [];
  let memSeq = 1;
  function idbTimeout() {
    return new Promise((_, rej) => setTimeout(() => rej(new Error("IndexedDB 逾時")), 6000));
  }
  function noteIdbFallback(err) {
    if (idbBroken) return;
    idbBroken = true;
    log("本機資料庫（IndexedDB）無法使用（" + (err && err.message ? err.message : err) + "），改用記憶體佇列：照片只保留到離開頁面為止。", "err");
  }
  function dbOpen() {
    return new Promise((res, rej) => {
      const r = indexedDB.open(DB_NAME, 1);
      r.onupgradeneeded = () => { r.result.createObjectStore(STORE, { keyPath: "id", autoIncrement: true }); };
      r.onsuccess = () => res(r.result);
      r.onerror = () => rej(r.error);
    });
  }
  function idbOp(fn) { return Promise.race([fn(), idbTimeout()]); }
  async function dbAll() {
    if (!idbBroken) {
      try {
        const db = await idbOp(dbOpen);
        return await idbOp(() => new Promise((res, rej) => {
          const q = db.transaction(STORE).objectStore(STORE).getAll();
          q.onsuccess = () => res(q.result.sort((a, b) => a.ts - b.ts));
          q.onerror = () => rej(q.error);
        }));
      } catch (e) { noteIdbFallback(e); }
    }
    return memItems.slice().sort((a, b) => a.ts - b.ts);
  }
  async function dbAdd(item) {
    if (!idbBroken) {
      try {
        const db = await idbOp(dbOpen);
        return await idbOp(() => new Promise((res, rej) => {
          const q = db.transaction(STORE, "readwrite").objectStore(STORE).add(item);
          q.onsuccess = () => res(q.result);
          q.onerror = () => rej(q.error);
        }));
      } catch (e) { noteIdbFallback(e); }
    }
    const id = memSeq++;
    memItems.push(Object.assign({ id }, item));
    return id;
  }
  async function dbDelete(id) {
    if (!idbBroken) {
      try {
        const db = await idbOp(dbOpen);
        await idbOp(() => new Promise((res, rej) => {
          const q = db.transaction(STORE, "readwrite").objectStore(STORE).delete(id);
          q.onsuccess = () => res();
          q.onerror = () => rej(q.error);
        }));
        return;
      } catch (e) { noteIdbFallback(e); }
    }
    const i = memItems.findIndex((x) => x.id === id);
    if (i >= 0) memItems.splice(i, 1);
  }
  async function dbClear() {
    if (!idbBroken) {
      try {
        const db = await idbOp(dbOpen);
        await idbOp(() => new Promise((res, rej) => {
          const q = db.transaction(STORE, "readwrite").objectStore(STORE).clear();
          q.onsuccess = () => res();
          q.onerror = () => rej(q.error);
        }));
        return;
      } catch (e) { noteIdbFallback(e); }
    }
    memItems.length = 0;
  }

  /* ---------------- EXIF 焦距 ---------------- */
  function parseTiff(dv, base) {
    const le = dv.getUint16(base, false) === 0x4949;
    const g16 = (o) => dv.getUint16(base + o, le);
    const g32 = (o) => dv.getUint32(base + o, le);
    function findTag(ifdOff, tag) {
      const count = g16(ifdOff);
      for (let i = 0; i < count; i++) { const e = ifdOff + 2 + i * 12; if (g16(e) === tag) return e; }
      return -1;
    }
    function readVal(e) {
      const type = g16(e + 2), cnt = g32(e + 4);
      if (type === 3 && cnt === 1) return g16(e + 8);
      if (type === 4 && cnt === 1) return g32(e + 8);
      if (type === 5 && cnt === 1) { const o = g32(e + 8); return g32(o) / (g32(o + 4) || 1); }
      if (type === 1 && cnt === 1) return dv.getUint8(base + e + 8);
      return null;
    }
    try {
      const ifd0 = g32(4);
      const subPtr = findTag(ifd0, 0x8769);
      if (subPtr < 0) return null;
      const subIfd = readVal(subPtr);
      if (!subIfd) return null;
      const t = findTag(subIfd, 0xA405); // FocalLengthIn35mmFilm
      if (t >= 0) { const v = readVal(t); if (v && v > 5 && v < 300) return v; }
    } catch (e) { /* ignore */ }
    return null;
  }
  async function readExifFocal35(blob) {
    try {
      const buf = await blob.slice(0, 256 * 1024).arrayBuffer();
      const dv = new DataView(buf);
      if (dv.getUint16(0) !== 0xFFD8) return null;
      let off = 2;
      while (off + 4 <= buf.byteLength) {
        const marker = dv.getUint16(off);
        if (marker === 0xFFE1) {
          if (dv.getUint32(off + 4) === 0x45786966) return parseTiff(dv, off + 10);
          return null;
        }
        if ((marker & 0xFF00) !== 0xFF00 || marker === 0xFFDA) break;
        off += 2 + dv.getUint16(off + 2);
      }
    } catch (e) { /* ignore */ }
    return null;
  }

  /* ---------------- 佇列 UI ---------------- */
  async function refreshQueue() {
    const items = await dbAll();
    const box = $("thumbs");
    box.innerHTML = "";
    for (const it of items) {
      const fig = document.createElement("figure");
      const img = document.createElement("img");
      img.src = URL.createObjectURL(it.blob);
      img.alt = it.name;
      const cap = document.createElement("figcaption");
      cap.textContent = it.name.length > 14 ? it.name.slice(0, 13) + "…" : it.name;
      const del = document.createElement("span");
      del.className = "del"; del.textContent = " ✕刪除";
      del.onclick = async () => { await dbDelete(it.id); refreshQueue(); };
      cap.appendChild(del);
      fig.appendChild(img); fig.appendChild(cap);
      box.appendChild(fig);
    }
    $("queueInfo").textContent = items.length
      ? `佇列裡有 ${items.length} 張照片${items.length >= 12 ? "，可以重建了" : `（建議至少 12 張，目前 ${items.length} 張）`}`
      : "佇列是空的";
    $("btnRun").disabled = items.length < 5;
    return items;
  }

  async function addBlob(blob, name, focalPxKnown) {
    let focalPx = focalPxKnown || null;
    let bmp = null;
    try { bmp = await createImageBitmap(blob); } catch (e) { /* keep null */ }
    if (!focalPx && bmp) {
      const f35 = await readExifFocal35(blob);
      if (f35) focalPx = Math.round((f35 / 36) * bmp.width);
    }
    await dbAdd({ blob, name, focalPx, ts: Date.now() + Math.random() });
    if (bmp && bmp.close) bmp.close();
  }

  $("btnCamera").onclick = () => $("fileCamera").click();
  $("btnPick").onclick = () => $("filePick").click();
  $("fileCamera").onchange = async (e) => {
    const f = e.target.files[0];
    if (f) { viewerMsg("climb-splat-pause"); await addBlob(f, f.name || "camera.jpg"); await refreshQueue(); viewerMsg("climb-splat-resume"); }
    e.target.value = "";
  };
  $("filePick").onchange = async (e) => {
    if (e.target.files.length) viewerMsg("climb-splat-pause");
    for (const f of e.target.files) await addBlob(f, f.name || "photo.jpg");
    await refreshQueue();
    viewerMsg("climb-splat-resume");
    e.target.value = "";
  };
  $("btnExamples").onclick = async () => {
    $("btnExamples").disabled = true;
    viewerMsg("climb-splat-pause");
    log("載入範例照片組（15 張）…");
    try {
      for (let i = 1; i <= 15; i++) {
        const name = "ex" + String(i).padStart(2, "0") + ".jpg";
        let blob;
        if (window.__EXAMPLE_PHOTOS__ && window.__EXAMPLE_PHOTOS__[name]) {
          // GitHub 發布版：範例照以 base64 內嵌於 examples-data.js（發布管道無法推送二進位檔）
          const b64 = window.__EXAMPLE_PHOTOS__[name];
          const bin = atob(b64);
          const arr = new Uint8Array(bin.length);
          for (let k = 0; k < bin.length; k++) arr[k] = bin.charCodeAt(k);
          blob = new Blob([arr], { type: "image/jpeg" });
        } else {
          const resp = await fetch("assets/examples/" + name);
          if (!resp.ok) throw new Error(name + " 載入失敗（HTTP " + resp.status + "）");
          blob = await resp.blob();
        }
        // 這組範例照的相機焦距已知 (COLMAP 離線標定: 1280px 寬時 f=1068px)
        await addBlob(blob, "範例 " + name, 1068);
      }
      await refreshQueue();
      log("範例照片組已載入，可以按「開始重建」。", "ok");
    } catch (err) {
      // 不用 alert()：在 app 的內嵌頁面裡 alert 不會顯示，錯誤只寫進頁面紀錄。
      log("載入範例失敗：" + (err && err.message ? err.message : err), "err");
      $("runState").textContent = "範例載入失敗";
    }
    viewerMsg("climb-splat-resume");
    $("btnExamples").disabled = false;
  };
  $("btnClear").onclick = async () => { await dbClear(); await refreshQueue(); };

  /* ---------------- 檢視器協調 ----------------
   * 檢視器就畫在本頁面的 canvas 上（不再用 iframe 載入獨立頁面），
   * 渲染迴圈和本頁面共用同一個主執行緒；在載入照片或跑 SfM 這些
   * 重活期間，請檢視器先把算力讓出來，否則光柵化占滿 CPU 時，
   * 佇列寫入與按鈕回呼會被拖到像「沒反應」。 */
  function viewerMsg(msg) {
    if (!window.ClimbViewer) return;
    if (msg === "climb-splat-pause") window.ClimbViewer.setPaused(true);
    else if (msg === "climb-splat-resume") window.ClimbViewer.setPaused(false);
  }

  /* ---------------- 檢視器切換 ---------------- */
  function showViewer(url, note, which) {
    if (window.ClimbViewer) {
      if (which === "mine" && lastResultUrl) window.ClimbViewer.showUrl(lastResultUrl);
      else window.ClimbViewer.showReference();
    }
    $("viewerNote").textContent = note;
    $("btnRef").classList.toggle("active", which === "ref");
    $("btnMine").classList.toggle("active", which === "mine");
  }
  $("btnRef").onclick = () => showViewer(null,
    "目前顯示：離線以 COLMAP 用 128 張照片重建的參考模型（品質上限對照）。", "ref");
  $("btnMine").onclick = () => {
    if (lastResultUrl) showViewer(lastResultUrl,
      "目前顯示：你在本機瀏覽器裡重建的結果。", "mine");
  };

  /* ---------------- OpenCV 載入 ---------------- */
  function loadOpenCV() {
    if (cvReadyPromise) return cvReadyPromise;
    cvReadyPromise = (async () => {
      // GitHub 發布版：opencv.js 拆成 3 段供應（發布管道有請求大小上限），
      // fetch 後合併成單一 script 注入，執行的位元組與整檔版逐位元組相同。
      const partUrls = ["assets/opencv-part1.js", "assets/opencv-part2.js", "assets/opencv-part3.js"];
      const texts = [];
      for (const p of partUrls) {
        const resp = await fetch(p);
        if (!resp.ok) throw new Error("opencv.js 載入失敗（" + p + " HTTP " + resp.status + "）");
        texts.push(await resp.text());
      }
      const blobUrl = URL.createObjectURL(new Blob([texts.join("")], { type: "text/javascript" }));
      await new Promise((resolve, reject) => {
        const s = document.createElement("script");
        s.src = blobUrl;
        s.onload = () => resolve();
        s.onerror = () => reject(new Error("opencv.js 載入失敗"));
        document.head.appendChild(s);
      });
      const t0 = Date.now();
      await new Promise((resolve, reject) => {
        const timer = setInterval(() => {
          if (typeof cv !== "undefined" && cv.Mat) { clearInterval(timer); resolve(); }
          else if (Date.now() - t0 > 90000) { clearInterval(timer); reject(new Error("OpenCV 初始化逾時")); }
        }, 150);
      });
    })();
    return cvReadyPromise;
  }

  /* ---------------- 執行重建 ---------------- */
  const STAGE_ZH = {
    features: "擷取特徵（AKAZE）", matching: "影像兩兩匹配+幾何驗證",
    init: "建立初始模型", register: "逐張註冊相機位姿",
  };
  $("btnRun").onclick = async () => {
    // 先在頁面紀錄留下回饋再做任何 await：就算後面的步驟卡住或失敗，
    // 使用者也看得到「有在動」和失敗原因，而不是按了完全沒反應。
    clearLog();
    log("開始重建：讀取照片佇列…");
    $("runState").textContent = "準備中…";
    viewerMsg("climb-splat-pause");
    const items = await dbAll();
    if (items.length < 5) {
      log(`照片太少，至少需要 5 張（建議 12–20 張）；目前佇列有 ${items.length} 張。先按「載入範例照片組（15 張）」或加入自己的照片。`, "err");
      $("runState").textContent = "照片不足";
      viewerMsg("climb-splat-resume");
      return;
    }
    $("btnRun").disabled = true;
    log(`開始重建：共 ${items.length} 張照片，全程在本機執行（不經過網路）。`);
    const t0 = performance.now();
    try {
      log("載入 OpenCV.js（WASM，約 10 MB，僅第一次需要）…");
      await loadOpenCV();
      log("OpenCV 就緒。", "ok");
      const images = [];
      for (const it of items) {
        const bitmap = await createImageBitmap(it.blob);
        images.push({ bitmap, width: bitmap.width, height: bitmap.height, name: it.name, focalPx: it.focalPx || undefined });
      }
      log("照片解碼完成，開始 SfM 管線…");
      let lastStage = "";
      const res = await window.ClimbSfM.runSfM(images, (stage, a, b) => {
        if (stage !== lastStage) { log(`— ${STAGE_ZH[stage] || stage}`, "hl"); lastStage = stage; }
        $("runState").textContent = `${STAGE_ZH[stage] || stage}：${a}/${b}`;
        if (stage === "features" || stage === "matching") log(`${STAGE_ZH[stage]} ${a}/${b}`);
        else log(`${STAGE_ZH[stage]}：已註冊 ${a}/${b}`);
      });
      const secs = ((performance.now() - t0) / 1000).toFixed(0);
      log(`SfM 完成：註冊 ${res.registered}/${res.total} 張，原始點 ${res.rawPoints}，保留 ${res.xyz.length / 3} 點。`, "ok");
      if (res.registered < res.total)
        log(`提醒：有 ${res.total - res.registered} 張照片沒註冊成功（重疊不足或紋理太少），成果來自其餘 ${res.registered} 張。`, "err");
      log("把點雲轉成 Gaussian splats…");
      const buf = window.ClimbSfM.pointsToSplat(res.xyz, res.rgb, 12000);
      const blob = new Blob([buf], { type: "application/octet-stream" });
      if (lastResultUrl) URL.revokeObjectURL(lastResultUrl);
      lastResultUrl = URL.createObjectURL(blob);
      $("stats").style.display = "flex";
      $("stReg").textContent = `${res.registered}/${res.total}`;
      $("stPts").textContent = (buf.byteLength / 32).toLocaleString();
      $("stTime").textContent = `${secs} 秒`;
      $("btnMine").disabled = false;
      $("btnDownload").disabled = false;
      showViewer(lastResultUrl,
        "目前顯示：你在本機瀏覽器裡重建的結果。", "mine");
      log("完成！成果已載入上方檢視器。", "ok");
      $("runState").textContent = "完成";
    } catch (err) {
      log("重建失敗：" + (err && err.message ? err.message : err), "err");
      $("runState").textContent = "失敗";
    }
    viewerMsg("climb-splat-resume");
    $("btnRun").disabled = false;
  };
  $("btnDownload").onclick = () => {
    if (!lastResultUrl) return;
    const a = document.createElement("a");
    a.href = lastResultUrl;
    a.download = "my-reconstruction.splat";
    a.click();
  };

  refreshQueue().catch((err) => {
    // 佇列 UI 更新失敗也不能讓後面的按鈕綁定看起來像壞掉
    log("佇列讀取失敗：" + (err && err.message ? err.message : err), "err");
    $("btnRun").disabled = true;
  });
})();
